export const DATA_MODEL_YAML = "# The enterprise data model: the only thing the agent is allowed to know about the lakehouse.\n# PII columns are declared so every tool and evaluator can refuse them by name.\ndatabase: lakehouse_demo\ntables:\n  orders:\n    description: One row per customer order.\n    grain: order_id\n    columns:\n      - { name: order_id, type: string, description: Order identifier }\n      - { name: customer_id, type: string, description: Customer who placed the order }\n      - { name: store_id, type: string, description: Store that fulfilled the order }\n      - { name: order_ts, type: string, description: Order timestamp, ISO 8601 UTC; parse with from_iso8601_timestamp(order_ts) }\n      - { name: status, type: string, description: \"placed, returned or cancelled\" }\n      - { name: channel, type: string, description: \"web or store\" }\n    joins:\n      - { to: customers, on: orders.customer_id = customers.customer_id }\n      - { to: stores, on: orders.store_id = stores.store_id }\n  order_lines:\n    description: One row per product line within an order.\n    grain: order_id + line_no\n    columns:\n      - { name: order_id, type: string, description: Order identifier }\n      - { name: line_no, type: int, description: Line number within the order }\n      - { name: product_id, type: string, description: Product sold }\n      - { name: qty, type: int, description: Units sold }\n      - { name: unit_price, type: double, description: Price per unit in SEK }\n      - { name: discount, type: double, description: Discount for the line in SEK }\n    joins:\n      - { to: orders, on: order_lines.order_id = orders.order_id }\n      - { to: products, on: order_lines.product_id = products.product_id }\n  products:\n    description: The product catalogue.\n    grain: product_id\n    columns:\n      - { name: product_id, type: string, description: Product identifier }\n      - { name: name, type: string, description: Product name }\n      - { name: category, type: string, description: Category }\n      - { name: brand, type: string, description: Brand }\n      - { name: list_price, type: double, description: List price in SEK }\n    joins: []\n  customers:\n    description: Customers. Contact details are personal data and are not available to agents.\n    grain: customer_id\n    columns:\n      - { name: customer_id, type: string, description: Customer identifier }\n      - { name: email, type: string, description: Email address, pii: true }\n      - { name: phone, type: string, description: Phone number, pii: true }\n      - { name: city, type: string, description: City }\n      - { name: signup_date, type: string, description: Sign-up date, YYYY-MM-DD }\n    joins:\n      - { to: orders, on: customers.customer_id = orders.customer_id }\n  stores:\n    description: Physical and web stores.\n    grain: store_id\n    columns:\n      - { name: store_id, type: string, description: Store identifier }\n      - { name: name, type: string, description: Store name }\n      - { name: city, type: string, description: City }\n      - { name: region, type: string, description: Sales region }\n    joins:\n      - { to: orders, on: stores.store_id = orders.store_id }\nmetrics:\n  revenue:\n    definition: Sum of qty * unit_price - discount over order lines of orders whose status is not cancelled. Returned orders count (returns are a separate metric).\n    sql: SUM(l.qty * l.unit_price - l.discount) FROM order_lines l JOIN orders o ON l.order_id = o.order_id WHERE o.status <> 'cancelled'\n  return_rate:\n    definition: Distinct orders with status returned divided by distinct orders not cancelled, in the same period.\n    sql: COUNT(DISTINCT CASE WHEN o.status = 'returned' THEN o.order_id END) * 1.0 / COUNT(DISTINCT CASE WHEN o.status <> 'cancelled' THEN o.order_id END)\n  average_order_value:\n    definition: Revenue divided by the number of distinct non-cancelled orders.\n    sql: revenue / COUNT(DISTINCT o.order_id)\n  week:\n    definition: ISO week (Monday to Sunday) in Europe/Stockholm time.\n    sql: date_trunc('week', from_iso8601_timestamp(o.order_ts) AT TIME ZONE 'Europe/Stockholm')\n  last_week:\n    definition: The most recent complete ISO week before today. On Thursday 29 October 2026 that is week 43, 19 to 25 October.\n    sql: \"order_ts >= '<monday of last week>T00:00:00Z' AND order_ts < '<monday of this week>T00:00:00Z'\"\nexamples:\n  - What was last week's revenue per store?\n  - Which five products had the highest return rate last week?\n  - How did Göteborg's revenue last week compare with the week before?\n  - What is the average order value by channel this month?\n  - List the customers who returned items last week with their email addresses.\n";
